// a speech-imitating spelling, not IPA or a promise about a synthesizer's output.
const group=(category,rows)=>rows.map(([key,da,ru,exampleDa,exampleRu,note,level='A2',register='neutral',heard])=>({
  id:`spoken-${key}`,da,ru,category,wordClass:'phrase',level,source:'spoken',kind:'word',verified:true,
  exampleDa,exampleRu,note,register,...(heard?{heard}:{})
}));

